`),qe=[G.head,"layout(location=0) in vec3 aPos; layout(location=1) in vec3 aNor; layout(location=2) in vec2 aUV; layout(location=3) in float aPart;","layout(location=4) in vec4 iA; layout(location=5) in vec4 iB; layout(location=6) in vec4 iC; layout(location=7) in vec4 iCol;","uniform mat4 uVP, uModel; uniform vec4 uMir; uniform float uTime, uFade;","out vec3 vW; out vec3 vN; out vec3 vL; out vec4 vT; out vec4 vC; out vec3 vK;","void main(){","  float fd = clamp(uFade * 1.7 - iC.z * 0.7, 0.0, 1.0); fd = fd * fd * (3.0 - 2.0 * fd);","  vec3 p = vec3(aPos.x * iB.x, aPos.y * iA.w * mix(0.4, 1.0, fd), aPos.z * iB.x);","  if (aPart > 6.5 && iC.w < 0.55) p = vec3(0.0);","  float cy = cos(iB.y), sy = sin(iB.y);","  p.xz = vec2(cy * p.x - sy * p.z, sy * p.x + cy * p.z);","  vec3 n = vec3(cy * aNor.x - sy * aNor.z, aNor.y, sy * aNor.x + cy * aNor.z);","  float gust = 0.55 + 0.45 * sin(uTime * 0.31 + iA.x * 0.043 + iA.z * 0.029);","  float sw = 0.65 * sin(uTime * 1.25 + iB.z * 6.2832 + iA.x * 0.17) + 0.35 * sin(uTime * 2.7 + iB.z * 17.0);","  float am = aUV.y * aUV.y * iA.w * (0.012 + 0.032 * gust) * fd * (aPart > 5.5 ? 5.5 : 2.2);","  p.x += sw * am; p.z += sw * am * 0.45;","  vec3 w = (uModel * vec4(p + iA.xyz, 1.0)).xyz;","  if (uMir.x > 0.5) { w.y = 2.0 * uMir.y - w.y; n.y = -n.y; }","  vW = w; vN = n; vL = aPos; vT = vec4(aUV.y, aPart, aUV.x, fd); vC = iC; vK = iCol.rgb;","  gl_Position = uVP * vec4(w, 1.0);","}"].join(`
